// client/src/components/RouletteWheel.jsx

import React, { useRef, useEffect, useState } from 'react';
import { getRouletteRewards } from '../api/rouletteApi';

// 💡 룰렛 보상 목록 데이터를 부모(Roulette.jsx)로부터 받습니다.
// 룰렛 UI를 구현하기 위해 필요한 최소한의 props만 사용합니다.

/**
 * SVG 기반 룰렛 휠 구현
 * @param {Array} rewards - 백엔드에서 가져온 룰렛 보상 목록 (name, probability, type 등 포함)
 * @param {boolean} isSpinning - 룰렛 회전 상태
 * @param {object} spinResult - 서버에서 받은 최종 결과 객체 { reward, coupon, message }
 * @param {number} rotationAngle - 룰렛을 멈출 최종 각도
 */
function RouletteWheel({ rewards, isSpinning, spinResult, rotationAngle, onSpin, disabled, spinCost }) {
    
    const wheelRef = useRef(null);
    const [segments, setSegments] = useState([]);

    // --- 1. 유틸리티 함수 ---
    function degToRad(d) { return (d * Math.PI) / 180; }
    
    // --- 2. 보상 데이터를 SVG 세그먼트 데이터로 변환 ---
    useEffect(() => {
        // 부모에서 rewards를 전달하면 그것을 사용
        if (rewards && rewards.length > 0) {
            setSegments(rewards.map(r => ({ label: r.name, key: r.name, type: r.type })));
            return;
        }

        // 부모에서 전달하지 않았으면 내부에서 API로 불러옵니다.
        let mounted = true;
        const fetch = async () => {
            try {
                const data = await getRouletteRewards();
                if (!mounted) return;
                if (data && data.length > 0) setSegments(data.map(r => ({ label: r.name, key: r.name, type: r.type })));
            } catch (err) {
                console.warn('Failed to load roulette rewards in RouletteWheel:', err);
            }
        };
        fetch();

        return () => { mounted = false; };
    }, [rewards]);
    
    // --- 3. 애니메이션 및 회전 처리 ---
    // 애니메이션 관리: isSpinning=true일 때는 CSS 무한회전 클래스를 적용하고,
    // isSpinning가 false로 변경되면 최종 rotationAngle로 서서히 멈춥니다.
    useEffect(() => {
        const wheel = wheelRef.current;
        if (!wheel || segments.length === 0) return;

        if (isSpinning) {
            // 무한 회전(빠르게 돔)
            wheel.classList.add('spinning');
            // 초기 transform을 그대로 두고 CSS 애니메이션에 맡깁니다.
            wheel.style.transition = '';
        } else {
            // 멈추는 애니메이션: spinning 클래스 제거 후 transform으로 회전 각도 적용
            wheel.classList.remove('spinning');
            // 4초 동안 완만하게 멈추도록 transition 적용
            wheel.style.transition = 'transform 4s cubic-bezier(.12,.7,.12,1)';
            wheel.style.transform = `rotate(${rotationAngle}deg)`;
        }
    }, [isSpinning, rotationAngle, segments.length]);


    // --- 4. SVG 렌더링 설정 ---
    if (segments.length === 0) {
        return <div className="text-center p-8 text-gray-500">룰렛 데이터 로드 중...</div>;
    }
    
    const radius = 180; // increased size for more presence
    const center = radius + 6; // SVG 중앙 좌표

    // helper: small inline SVG icons per segment type
    const renderSegmentIcon = (type, size = 18) => {
        if (type === 'POINTS') {
            return (
                <g className="segment-icon" transform={`translate(${-6},${-6})`}>
                    <circle cx={0} cy={0} r={size/2} fill="#ffd454" stroke="#ffb84d" strokeWidth={1} />
                    <text x={0} y={3} textAnchor="middle" fontSize={10} fontWeight={800} fill="#7a3e00">P</text>
                </g>
            );
        }
        if (type === 'COUPON') {
            return (
                <g className="segment-icon" transform={`translate(${-6},${-6})`}>
                    <rect x={-size/2} y={-size/3} width={size} height={size/1.6} rx={2} fill="#ffd1f0" stroke="#ff9ad6" strokeWidth={1} />
                    <text x={0} y={3} textAnchor="middle" fontSize={9} fontWeight={800} fill="#7a0b3a">%</text>
                </g>
            );
        }
        return null;
    };

    // confetti: spawn simple divs inside wheel-wrapper when spin finishes
    const wheelWrapperRef = useRef(null);
    useEffect(() => {
        if (!spinResult) return;
        // small celebration only on success
        const success = spinResult.success !== false;
        if (!success) return;
        const wrapper = wheelWrapperRef.current;
        if (!wrapper) return;

        const confettiCount = 18;
        const confettis = [];
        for (let i = 0; i < confettiCount; i++) {
            const el = document.createElement('div');
            el.className = 'confetti';
            el.style.background = ['#ff6b6b','#ffd166','#6bf3ff','#c39bff'][i % 4];
            el.style.left = `${50 + (Math.random() - 0.5) * 60}%`;
            el.style.top = `${50 + (Math.random() - 0.5) * 30}%`;
            el.style.transform = `translate(-50%,-50%) rotate(${Math.random()*360}deg)`;
            wrapper.appendChild(el);
            confettis.push(el);
            // remove after animation
            el.addEventListener('animationend', () => { el.remove(); });
        }

        // short chime sound using WebAudio (user gesture already occurred)
        try {
            const ctx = new (window.AudioContext || window.webkitAudioContext)();
            const o = ctx.createOscillator();
            const g = ctx.createGain();
            o.type = 'sine';
            o.frequency.setValueAtTime(880, ctx.currentTime);
            g.gain.setValueAtTime(0.0001, ctx.currentTime);
            g.gain.exponentialRampToValueAtTime(0.12, ctx.currentTime + 0.01);
            o.connect(g); g.connect(ctx.destination); o.start();
            o.frequency.exponentialRampToValueAtTime(660, ctx.currentTime + 0.12);
            g.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 0.6);
            o.stop(ctx.currentTime + 0.65);
        } catch (e) {
            // ignore audio errors
        }

    }, [spinResult]);
    return (
        <div className="wheel-container" style={{ padding: 20 }}>
            <div className="wheel-wrapper card" ref={wheelWrapperRef}>
                <div className={`wheel-rotator ${isSpinning ? 'spinning' : ''}`} ref={wheelRef} style={{ transformOrigin: 'center center' }}>
                    <svg width={(radius * 2) + 12} height={(radius * 2) + 12} viewBox={`0 0 ${center * 2} ${center * 2}`}>
                        {/* translate to center inside the svg so segment coords are relative */}
                        <defs>
                            <radialGradient id="segGloss" cx="30%" cy="20%" r="80%">
                                <stop offset="0%" stopColor="rgba(255,255,255,0.28)" />
                                <stop offset="60%" stopColor="rgba(255,255,255,0.06)" />
                                <stop offset="100%" stopColor="rgba(255,255,255,0)" />
                            </radialGradient>
                        </defs>
                        <g transform={`translate(${center},${center})`}>
                        {segments.map((seg, i) => {
                            const angle = 360 / segments.length;
                            const start = i * angle;
                            const largeArc = angle > 180 ? 1 : 0;
                            
                            // 세그먼트의 색상 설정
                            // vivid colors per type with variant by index for contrast
                            const palette = [
                                ['#ffe9e6','#ffb3a7'],
                                ['#fff3cc','#ffd27a'],
                                ['#e8f6ff','#a9e0ff'],
                                ['#e9f8ee','#b8f0c3'],
                                ['#fff0f6','#ffbfdc'],
                                ['#f8f0ff','#d9b3ff'],
                            ];
                            let base, accent;
                            if (seg.type === 'COUPON') { base = '#fff4db'; accent = '#ffd47a'; }
                            else if (seg.type === 'POINTS') { base = '#e8f6ff'; accent = '#9ee0ff'; }
                            else { base = '#f6f6f6'; accent = '#e0e0e0'; }
                            // alternate colors using index for variety
                            const idx = i % palette.length;
                            let fill;
                            // pick a vivid base from palette to make it punchy (coupang-like mix)
                            const chosen = palette[idx];
                            const baseColor = seg.type === 'COUPON' ? '#ffd47a' : (seg.type === 'POINTS' ? '#9ee0ff' : '#f5f5f5');
                            const accentColor = chosen[1];
                            fill = `url(#segGloss)`;

                            // Path D 속성 계산 (M 0 0 L x1 y1 A r r 0 largeArc 1 x2 y2 Z)
                            const path = `M ${0} ${0} L ${radius * Math.cos(degToRad(start))} ${radius * Math.sin(degToRad(start))} A ${radius} ${radius} 0 ${largeArc} 1 ${radius * Math.cos(degToRad(start + angle))} ${radius * Math.sin(degToRad(start + angle))} Z`;
                            
                            // 텍스트 위치 계산
                            const textAngle = start + angle / 2;
                            const textX = (radius / 1.5) * Math.cos(degToRad(textAngle));
                            const textY = (radius / 1.5) * Math.sin(degToRad(textAngle));
                            const iconX = (radius / 2.3) * Math.cos(degToRad(textAngle));
                            const iconY = (radius / 2.3) * Math.sin(degToRad(textAngle));

                            return (
                                <g key={seg.key + i}>
                                    <path d={path} fill={baseColor} stroke={accentColor} strokeWidth={1} />
                                    <path d={path} fill={fill} style={{ mixBlendMode: 'overlay', opacity: 0.5 }} />
                                    <g transform={`translate(${iconX}, ${iconY}) rotate(${textAngle})`}>
                                        {renderSegmentIcon(seg.type)}
                                    </g>
                                    <text 
                                        x={textX} 
                                        y={textY} 
                                        fill="#333" 
                                        fontSize={10} 
                                        textAnchor="middle" 
                                        alignmentBaseline="middle" 
                                        transform={`rotate(${textAngle} ${textX} ${textY})`} // 텍스트 회전
                                    >
                                        {seg.label}
                                    </text>
                                </g>
                            );
                        })}
                        </g>
                    </svg>

                {/* center heart button (visible when onSpin provided) */}
                {onSpin && (
                    <div className="wheel-center">
                        <div className="center-ring" />
                        <button
                            className={`heart-button ${disabled || isSpinning ? 'disabled' : ''}`}
                            onClick={() => {
                                if (disabled || isSpinning) return;
                                onSpin();
                            }}
                            disabled={disabled || isSpinning}
                            aria-label="Spin the wheel"
                        >
                            <svg viewBox="0 0 24 24" width="44" height="44" className="heart-icon" xmlns="http://www.w3.org/2000/svg">
                                <defs>
                                    <linearGradient id="heartGrad" x1="0" x2="1">
                                        <stop offset="0%" stopColor="#ff8a80" />
                                        <stop offset="100%" stopColor="#ff3d00" />
                                    </linearGradient>
                                </defs>
                                <path fill="url(#heartGrad)" d="M12 21s-7-4.35-9-6.5C-1 11 3 6 6 6c1.9 0 3 1.2 3 1.2S11.1 6 13 6c3 0 7 5 3 8.5C19 16.65 12 21 12 21z" />
                            </svg>
                            {spinCost != null && (
                                <div className="spin-cost">-{spinCost}</div>
                            )}
                        </button>
                    </div>
                )}
                {/* 포인터 (지시계) */}
                    <div className="pointer bounce" style={{ position: 'absolute', left: '50%', top: -12, transform: 'translateX(-50%)', width: 0, height: 0, borderLeft: '14px solid transparent', borderRight: '14px solid transparent', borderBottom: '22px solid #ff5252', zIndex:50 }} />
                </div>
            </div>
        </div>
    );
}

export default RouletteWheel;
